  const vat2 = Math.round(base2 * 0.09);
  const due = base1 + base2 + vat1 + vat2;
  const expectedFee = Math.round(due * 1 * 0.0004);
  assert.equal(fee, expectedFee);
});

test('lateFee exactly 0 when due', () => {
  const invoice = {
    dueDate: '2026-10-15',
    lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const fee = lateFee(invoice, '2026-10-15');
  assert.strictEqual(fee, 0);
});

test('lateFee rounding is done after calculation', () => {
  const invoice = {
    dueDate: '2026-10-01',
    lines: [{ qty: 1, unitPrice: 1, discountPercent: 0, vatRate: 21 }],
  };
  const fee = lateFee(invoice, '2026-10-02');
  const due = 1 + Math.round(1 * 0.21);
  const rawFee = due * 1 * 0.0004;
  const expectedFee = Math.round(rawFee);
  assert.equal(fee, expectedFee);
});

test('lateFee with invoice with voucher', () => {
  const invoice = {
    dueDate: '2026-10-01',
    lines: [{ qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
    voucher: { code: 'SUMMER20', amount: 500 },
  };
  const fee = lateFee(invoice, '2026-10-02');
  const subtotal = 5000;
  const vat = Math.round(subtotal * 0.21);
  const due = subtotal + vat - 500;
  const expectedFee = Math.round(due * 1 * 0.0004);
  assert.equal(fee, expectedFee);
});

test('lateFee large days overdue', () => {
  const invoice = {
    dueDate: '2026-01-01',
    lines: [{ qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const fee = lateFee(invoice, '2026-12-31');
  const due = 5000 + Math.round(5000 * 0.21);
  const daysOverdue = 364;
  const expectedFee = Math.round(due * daysOverdue * 0.0004);
  assert.equal(fee, expectedFee);
});

