  const result = vatSummary(invoices);
  const lineTotal = 5 * 8500;
  const discount = lineTotal * 0.05;
  const base = lineTotal - discount;
  const expectedVat = Math.round(base * 0.21);
  assert.equal(result[0].base, base);
  assert.equal(result[0].vat, expectedVat);
