        { qty: 3, unitPrice: 1000, discountPercent: 5, vatRate: 21 },
      ],
    },
  ];
  const result = vatSummary(invoices);
  const base1 = 5000 - 500;
  const base2 = 3000 - 150;
  const vat1 = Math.round(base1 * 0.21);
  const vat2 = Math.round(base2 * 0.21);
  assert.equal(result[0].base, base1 + base2);
  // vat1 = 945, vat2 = 598 (roundCents(598.5) = 598), total = 1543
  assert.equal(result[0].vat, 1543);
});

